function terrain(){let w=view.w,h=view.h;let sky=ctx.createLinearGradient(0,0,0,h*.64);sky.addColorStop(0,'#506953');sky.addColorStop(.55,'#8e9b72');sky.addColorStop(1,'#c7bd8a');ctx.fillStyle=sky;ctx.fillRect(0,0,w,h);let sunX=w*.74-player.yaw*22,sunY=h*.19;let glow=ctx.createRadialGradient(sunX,sunY,5,sunX,sunY,h*.19);glow.addColorStop(0,'rgba(250,237,182,.42)');glow.addColorStop(1,'rgba(250,237,182,0)');ctx.fillStyle=glow;ctx.fillRect(sunX-h*.2,sunY-h*.2,h*.4,h*.4);ctx.fillStyle='rgba(232,224,177,.8)';ctx.beginPath();ctx.arc(sunX,sunY,Math.max(14,h*.024),0,Math.PI*2);ctx.fill();
 let hor=h*.46+player.pitch*h*.25;for(let layer=0;layer<3;layer++){ctx.beginPath();ctx.moveTo(0,hor+layer*h*.035);for(let i=0;i<=12;i++){let x=i*w/12,y=hor+layer*h*(.035+layer*.025)+Math.sin(i*1.7+layer*4+player.yaw*2)*h*(.015+layer*.006);ctx.lineTo(x,y)}ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.closePath();ctx.fillStyle=['#687d56','#536d4b','#425e43'][layer];ctx.fill()}
 let ground=ctx.createLinearGradient(0,hor,0,h);ground.addColorStop(0,'#3c5940');ground.addColorStop(.38,'#304d38');ground.addColorStop(1,'#1d3529');ctx.fillStyle=ground;ctx.fillRect(0,hor,w,h-hor);
 // Long perspective rows and moss flecks give the forest floor depth.
