}
function drawTree(t){let p=proj(t.x,t.z);if(!p||p.z>78)return null;let s=Math.min(p.scale,view.h*.13),baseY=p.horizon+s*.11;if(t.alive){let ht=Math.max(9,t.h*s*.42),width=Math.max(4,ht*(t.kind==='oak'?.68:t.kind==='redwood'?.38:.47));let sway=Math.sin(performance.now()*.001+t.sway)*s*.009;let crownY=baseY-ht;
