 }else if(t.kind==='oak'){
 ctx.strokeStyle='#554630';ctx.lineWidth=Math.max(2,width*.18);ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(0,-ht*.6);ctx.moveTo(0,-ht*.42);ctx.lineTo(-width*.45,-ht*.8);ctx.moveTo(0,-ht*.48);ctx.lineTo(width*.43,-ht*.77);ctx.stroke();for(let i=0;i<6;i++){let a=i*2.399+t.variant,r=width*(.22+rand()*.2),x=Math.cos(a)*width*.28,y=-ht*.75+Math.sin(a)*ht*.13;ctx.fillStyle=[t.color,shade(t.color,10),shade(t.color,-13)][i%3];ctx.beginPath();ctx.ellipse(x,y,r,r*.75,a,0,Math.PI*2);ctx.fill()}
 }else if(t.kind==='redwood'){
 ctx.fillStyle='#75553b';ctx.beginPath();ctx.moveTo(-width*.23,0);ctx.lineTo(-width*.16,-ht);ctx.lineTo(width*.15,-ht);ctx.lineTo(width*.22,0);ctx.fill();ctx.fillStyle='#435e3c';for(let i=0;i<5;i++){let y=-ht*(.45+i*.1),ww=width*(.55-i*.06);ctx.beginPath();ctx.moveTo(0,y-ht*.3);ctx.lineTo(ww,y+ht*.03);ctx.lineTo(-ww,y+ht*.03);ctx.fill()}
 }else{ctx.strokeStyle='#5e503b';ctx.lineWidth=Math.max(2,width*.13);ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(0,-ht);ctx.moveTo(0,-ht*.7);ctx.lineTo(-width*.35,-ht*.92);ctx.moveTo(0,-ht*.54);ctx.lineTo(width*.45,-ht*.79);ctx.stroke();for(let i=0;i<4;i++){ctx.strokeStyle='#7d7155';ctx.lineWidth=Math.max(1,width*.06);ctx.beginPath();ctx.moveTo(0,-ht*(.3+i*.14));ctx.lineTo((i%2?1:-1)*width*.4,-ht*(.4+i*.12));ctx.stroke()}}
