 }else if(t.fall>0){t.fall=Math.max(0,t.fall-.016);ctx.save();ctx.translate(p.x,baseY);ctx.rotate(t.fallDir*(1-t.fall)*1.45);ctx.fillStyle='#65503a';ctx.fillRect(-width*.09,-ht,width*.18,ht);ctx.fillStyle=t.color;ctx.beginPath();ctx.arc(0,-ht,width*.35,0,Math.PI*2);ctx.fill();ctx.restore()}else{ctx.fillStyle='#624b36';ctx.fillRect(p.x-width*.13,baseY-width*.06,width*.26,width*.06);ctx.fillStyle='#9e7b4f';ctx.fillRect(p.x-width*.1,baseY-width*.05,width*.2,width*.035)}return p.z}
