function shade(hex,amt){let n=parseInt(hex.slice(1),16),r=Math.max(0,Math.min(255,(n>>16)+amt)),g=Math.max(0,Math.min(255,((n>>8)&255)+amt)),b=Math.max(0,Math.min(255,(n&255)+amt));return`rgb(${r},${g},${b})`}
function pickTarget(){let best=null,score=Infinity;for(let t of trees){if(!t.alive)continue;let dx=t.x-player.x,dz=t.z-player.z,dist=Math.hypot(dx,dz);if(dist>8.3||dist<1.6)continue;let bearing=Math.atan2(dx,dz),angle=Math.atan2(Math.sin(bearing-player.yaw),Math.cos(bearing-player.yaw));let side=Math.abs(angle);if(side>.48)continue;let p=proj(t.x,t.z,t.h*.5);if(!p)continue;let screenErr=Math.abs(p.x-view.w/2)/view.w;let value=side*4+dist*.025+screenErr*.35;if(value<score){score=value;best=t}}return best}
function render(){let w=view.w,h=view.h;ctx.clearRect(0,0,w,h);terrain();let visible=[];for(let t of trees){let p=proj(t.x,t.z);if(!p||p.z>78)continue;visible.push({t,z:p.z})}visible.sort((a,b)=>b.z-a.z);screenTrees=[];for(let a of visible){let z=drawTree(a.t);if(z!==null)screenTrees.push(a.t)}target=active?pickTarget():null;let aimed=!!target;ui.reticle.classList.toggle('active',aimed);ui.targetReadout.classList.toggle('visible',aimed);ui.interaction.classList.toggle('visible',aimed);if(target){ui.targetName.textContent=target.name;ui.targetHp.style.width=`${Math.max(0,target.hp/target.maxHp*100)}%`;ui.targetDurability.textContent=`ODOLNOSŤ ${Math.ceil(target.hp/target.maxHp*100)}%`;ui.chopMeterName.textContent=target.name.toUpperCase()}updateMap();requestAnimationFrame(render)}
function updateMap(){let cellW=100,cellH=100;ui.mapGrid.innerHTML='';for(let t of trees){if(!t.alive)continue;let px=50+(t.x-player.x)*1.3,py=75-(t.z-player.z)*1.3;if(px<2||px>98||py<2||py>98)continue;let dot=document.createElement('i');dot.className='map-tree';dot.style.left=px+'%';dot.style.top=py+'%';ui.mapGrid.append(dot)}let me=document.createElement('i');me.className='map-player';me.style.left='50%';me.style.top='75%';ui.mapGrid.append(me);ui.sector.textContent=`${String.fromCharCode(65+Math.max(0,Math.min(7,Math.floor((player.x+40)/10))))}-${String(Math.max(1,Math.floor(player.z/10)+1)).padStart(2,'0')}`;ui.coords.textContent=`SÚRADNICE  ${Math.abs(player.x).toFixed(0)}° ${player.x<0?'W':'E'} · ${Math.max(0,player.z).toFixed(0)}° N`}
function setHUD(){ui.cash.textContent=Math.floor(cash).toLocaleString('sk');ui.totalCash.textContent='$'+Math.floor(totalEarned).toLocaleString('sk');ui.treeCount.textContent=`${cut} / ${W}`;ui.planetProgress.style.width=`${cut/W*100}%`;ui.progressText.textContent=`${Math.floor(cut/W*100)}%`;ui.woodCount.textContent=`${wood} KMEŇA`;ui.toolIcon.textContent=tools[tool].icon;ui.toolName.textContent=tools[tool].name;ui.toolSub.textContent=tools[tool].sub;ui.toolLevel.textContent=String(tool+1).padStart(2,'0');ui.planetStatus.textContent=cut>=80?'BIÓM 03 · STARÝ LES':cut>=40?'BIÓM 02 · DIVOKÝ HÁJ':'BIÓM 01 · STARÝ LES';ui.planetLabel.textContent=cut>=80?'OHNIVÁ ZÓNA':cut>=40?'DIVOKÝ HÁJ':'ZELENÁ ZÓNA'}
function sound(freq=180){if(!soundOn)return;try{ac=ac||new(window.AudioContext||window.webkitAudioContext)();let o=ac.createOscillator(),g=ac.createGain();o.type='triangle';o.frequency.setValueAtTime(freq,ac.currentTime);o.frequency.exponentialRampToValueAtTime(freq*.45,ac.currentTime+.12);g.gain.setValueAtTime(.055,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.15);o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+.16)}catch(e){}}
function notify(msg){ui.toast.textContent=msg;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),2100)}
function begin(){active=true;ui.modal.classList.add('closed');setHUD();notify('EXPEDÍCIA ZAČALA · PRIBLÍŽ SA K STROMU');if(innerWidth>800&&canvas.requestPointerLock)canvas.requestPointerLock();last=performance.now()}
function chop(){if(!active||!target)return;let t=target;t.hp-=tools[tool].damage;chopClock+=tools[tool].damage;ui.chopMeter.classList.add('visible');ui.chopMeterFill.style.width=`${Math.max(0,100-t.hp/t.maxHp*100)}%`;ui.chopPercent.textContent=`${Math.min(100,Math.floor((1-t.hp/t.maxHp)*100))}%`;ui.swingFx.classList.remove('active');void ui.swingFx.offsetWidth;ui.swingFx.classList.add('active');ui.woodGain.textContent=Math.max(8,Math.round(t.value*.55));sound(tool===1?290:tool===2?80:150);if(t.hp<=0){t.hp=0;t.alive=false;t.fall=1;cut++;let earnings=Math.round(t.value*tools[tool].bonus);cash+=earnings;totalEarned+=earnings;wood+=Math.max(8,Math.round(t.value*.55));setHUD();ui.cashGain.textContent=`+$${earnings}`;ui.cashGain.classList.remove('show');void ui.cashGain.offsetWidth;ui.cashGain.classList.add('show');setTimeout(()=>ui.cashGain.classList.remove('show'),1200);ui.chopMeter.classList.remove('visible');notify(`${t.name.toUpperCase()} VYRÚBANÝ · +$${earnings}`);sound(270);maybeUpgrade();if(cut>=W){setTimeout(showWin,650)}}}
function maybeUpgrade(){if(tool<2&&cash>=tools[tool+1].price){showUpgrade(tool+1);}}
function showUpgrade(which){upgradeMode=which;$('upgradeArt').textContent=tools[which].icon;$('upgradeTitle').textContent=tools[which].name;$('upgradeDescription').textContent=which===1?'Rýchle reťazové ostrie. Menej úderov, viac dreva.':'Horúca sila, ktorá premieňa celý les na zárobok.';$('upgradeSpeed').textContent=which===1?'×4':'×10';$('equipBtn').innerHTML=`KÚPIŤ ZA $${tools[which].price} <span>↗</span>`;$('equipBtn').disabled=cash<tools[which].price;$('equipBtn').style.opacity=cash<tools[which].price?'.45':'1';ui.upgrade.classList.remove('hidden');ui.modal.classList.remove('closed')}
function equip(){let price=tools[upgradeMode].price;if(cash<price){notify(`POTREBUJEŠ EŠTE $${price-cash}`);return}cash-=price;tool=upgradeMode;ui.upgrade.classList.add('hidden');ui.modal.classList.add('closed');setHUD();$('levelToastName').textContent=tools[tool].name;ui.levelToast.classList.add('show');setTimeout(()=>ui.levelToast.classList.remove('show'),3000);notify(`${tools[tool].name} VYBAVENÁ`)}
function showWin(){active=false;$('finalCash').textContent='$'+totalEarned.toLocaleString('sk');ui.win.classList.remove('hidden');ui.modal.classList.remove('closed');if(document.pointerLockElement)document.exitPointerLock()}
function restart(){location.reload()}

